use super::*;

/// The manifest with the table that owns the crate root — `[lib]`, or `[[bin]]` for a BINARY — pointing
/// at the SHARED crate root.
///
/// A binary reaches the shared root exactly as a library does; only the table differs. `bsc-hook` is
/// the proof: 165 lines, no lib, no child module, and after this it is a `Cargo.toml` and nothing else.
/// `pkg` names a `[[bin]]` table that has to be CREATED — cargo requires `name` there — and is unused
/// for `[lib]`, which needs none.
pub fn point_root_at_shared_root(cargo_toml: &str, crate_dir: &str, root_name: &str, pkg: &str) -> String {
    let table = root_table(root_name);
    let wiring = lib_path_for(crate_dir);
    if section_of(cargo_toml, table).lines().any(|l| l.trim() == wiring) {
        return cargo_toml.to_string();
    }
    let note = "# THE SHARED CRATE ROOT — this crate owns no source file at all. See\n\
                # crates/graph-materialize/crate_root.rs; the crate's own docs come from its record.";
    let mut lines: Vec<String> = cargo_toml.lines().map(str::to_string).collect();
    match lines.iter().position(|l| l.trim() == table) {
        Some(at) => {
            // An existing `path` inside THIS table is replaced in place; anything else keeps its order.
            let mut end = lines.iter().skip(at + 1).position(|l| l.trim_start().starts_with('[')).map_or(lines.len(), |i| at + 1 + i);
            // Back up over the blank line that separates this table from the next, so the key lands
            // INSIDE `[lib]` rather than orphaned above `[dependencies]` with the separator on the
            // wrong side of it.
            while end > at + 1 && lines[end - 1].trim().is_empty() {
                end -= 1;
            }
            match lines[at + 1..end].iter().position(|l| l.trim_start().starts_with("path")) {
                Some(i) => lines[at + 1 + i] = wiring,
                None => lines.insert(end, format!("{note}\n{wiring}")),
            }
        }
        None => {
            // A `[[bin]]` table cargo has been AUTO-DETECTING needs its `name` written down the moment
            // the path stops being `src/main.rs`, or cargo looks for a binary target that is not there.
            let name = if table == "[[bin]]" { format!("name = \"{pkg}\"\n") } else { String::new() };
            let mut block = format!("{table}\n{note}\n{name}{wiring}");
            if !cargo_toml.trim_end().is_empty() {
                block = format!("\n{block}");
            }
            lines.push(block);
        }
    }
    let mut out = lines.join("\n");
    if !out.ends_with('\n') {
        out.push('\n');
    }
    out
}
